// Prepara o pedido: mede a conversa e monta as instruções.
const item = $input.first();
const binarios = item.binary || {};
const campo = binarios.arquivo ? 'arquivo' : Object.keys(binarios)[0];
if (!campo) throw new Error('Arquivo não recebido: nenhum binário no webhook.');

let bruto;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, campo);
  bruto = buf.toString('utf8');
} catch (e) {
  bruto = Buffer.from(binarios[campo].data, 'base64').toString('utf8');
}
if (!bruto || bruto.length < 50) throw new Error('O arquivo chegou vazio (campo ' + campo + ').');
const corpo = item.json.body || item.json || {};

const analiseId = corpo.analiseId || corpo.analysisId;
const callbackUrl = corpo.callbackUrl;
const comAvancada = String(corpo.avancada) === 'true';
const remetente = corpo.remetente || null;
if (!analiseId || !callbackUrl) throw new Error('analiseId ou callbackUrl ausente.');

let respostas = [];
try { respostas = JSON.parse(corpo.respostas || '[]'); } catch (e) { respostas = []; }

/* ---------- 1. parsing ---------- */
const IOS = /^\[(\d{1,2})\/(\d{1,2})\/(\d{2,4}),?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*\]\s*([^:]{1,80}):\s*([\s\S]*)$/;
const ANDROID = /^(\d{1,2})\/(\d{1,2})\/(\d{2,4}),?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*-\s*([^:]{1,80}):\s*([\s\S]*)$/;
const MIDIA = /(mídia oculta|midia oculta|imagem ocultada|áudio ocultado|audio ocultado|vídeo omitido|figurinha omitida|omitted)/i;
const RUIDO = /(criptografadas de ponta a ponta|esta mensagem foi apagada|você apagou esta mensagem|criou o grupo|saiu do grupo|chamada de voz perdida)/i;

const msgs = [];
for (const linha of bruto.replace(/\u200e|\u200f|\u202a|\u202c/g, '').split(/\r?\n/)) {
  const achado = IOS.exec(linha) || ANDROID.exec(linha);
  if (!achado) {
    const ultima = msgs[msgs.length - 1];
    if (ultima && linha.trim()) ultima.texto += '\n' + linha.trim();
    continue;
  }
  const [, d, m, a, h, mi, s, autor, texto] = achado;
  if (RUIDO.test(texto)) continue;
  const ano = a.length === 2 ? 2000 + Number(a) : Number(a);
  const data = new Date(ano, Number(m) - 1, Number(d), Number(h), Number(mi), Number(s || 0));
  if (isNaN(data.getTime())) continue;
  msgs.push({ data, autor: autor.trim(), texto: texto.trim(), midia: MIDIA.test(texto) });
}

if (msgs.length < 15) throw new Error('Não conseguimos ler essa conversa (só ' + msgs.length + ' mensagens reconhecidas).');

/* ---------- 2. números ---------- */
const AFETO = /(amor|te amo|amo vc|saudade|carinho|meu bem|minha vida|beijo|bjo|❤|🥰|😍|😘|💕)/i;
const RISO = /(kkk|hahah|rsrs|😂|🤣)/i;
const DESCULPA = /(desculpa|desculpe|foi mal|me perdoa|perdão|perdao)/i;
const TENSAO = /(cansad|chatead|magoad|irritad|deixa pra lá|tanto faz|não quero falar|sempre a mesma coisa)/i;

const pad = (n) => String(n).padStart(2, '0');
const iso = (dt) => dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate()) + ' ' + pad(dt.getHours()) + ':' + pad(dt.getMinutes());
const mediana = (l) => { if (!l.length) return 0; const o = [...l].sort((x, y) => x - y); const k = Math.floor(o.length / 2); return o.length % 2 ? o[k] : (o[k - 1] + o[k]) / 2; };

const autores = [...new Set(msgs.map((m) => m.autor))];

const porAutor = autores.map((autor) => {
  const minhas = msgs.filter((m) => m.autor === autor);
  const txt = minhas.filter((m) => !m.midia);
  const palavras = txt.reduce((s, m) => s + m.texto.split(/\s+/).length, 0);
  return {
    autor,
    mensagens: minhas.length,
    midias: minhas.filter((m) => m.midia).length,
    palavrasPorMensagem: txt.length ? +(palavras / txt.length).toFixed(1) : 0,
    afeto: txt.filter((m) => AFETO.test(m.texto)).length,
    riso: txt.filter((m) => RISO.test(m.texto)).length,
    desculpas: txt.filter((m) => DESCULPA.test(m.texto)).length,
    tensao: txt.filter((m) => TENSAO.test(m.texto)).length,
    perguntas: txt.filter((m) => m.texto.includes('?')).length
  };
});

const primeiroDoDia = new Map();
for (const m of msgs) { const dia = iso(m.data).slice(0, 10); if (!primeiroDoDia.has(dia)) primeiroDoDia.set(dia, m.autor); }
const iniciativas = { diasComConversa: primeiroDoDia.size, porAutor: {} };
for (const a of primeiroDoDia.values()) iniciativas.porAutor[a] = (iniciativas.porAutor[a] || 0) + 1;

const esperas = {};
for (let i = 1; i < msgs.length; i++) {
  if (msgs[i - 1].autor === msgs[i].autor) continue;
  const min = (msgs[i].data - msgs[i - 1].data) / 60000;
  if (min < 0 || min > 1440) continue;
  (esperas[msgs[i].autor] = esperas[msgs[i].autor] || []).push(min);
}
const tempoResposta = {};
for (const [autor, lista] of Object.entries(esperas)) {
  tempoResposta[autor] = { respostas: lista.length, medianaMinutos: Math.round(mediana(lista)), acimaDe4h: lista.filter((v) => v > 240).length };
}

const meses = new Map();
for (const m of msgs) {
  const chave = iso(m.data).slice(0, 7);
  const mes = meses.get(chave) || { total: 0, afeto: 0, riso: 0, porAutor: {} };
  mes.total++;
  mes.porAutor[m.autor] = (mes.porAutor[m.autor] || 0) + 1;
  if (!m.midia && AFETO.test(m.texto)) mes.afeto++;
  if (!m.midia && RISO.test(m.texto)) mes.riso++;
  meses.set(chave, mes);
}

const porHora = new Array(24).fill(0);
const horasDeTensao = new Array(24).fill(0);
for (const m of msgs) { porHora[m.data.getHours()]++; if (!m.midia && TENSAO.test(m.texto)) horasDeTensao[m.data.getHours()]++; }

const silencios = [];
for (let i = 1; i < msgs.length; i++) {
  const horas = (msgs[i].data - msgs[i - 1].data) / 3600000;
  if (horas >= 24) silencios.push({ de: iso(msgs[i - 1].data), ate: iso(msgs[i].data), horas: Math.round(horas), quemVoltou: msgs[i].autor });
}
silencios.sort((a, b) => b.horas - a.horas);

const numeros = {
  periodo: { de: iso(msgs[0].data), ate: iso(msgs[msgs.length - 1].data), dias: Math.max(1, Math.round((msgs[msgs.length - 1].data - msgs[0].data) / 86400000)) },
  total: msgs.length,
  autores: porAutor,
  iniciativas,
  tempoResposta,
  porMes: [...meses.entries()].map(([mes, d]) => ({ mes, ...d })),
  porHora,
  horasDeTensao,
  silencios: silencios.slice(0, 5)
};

/* ---------- 3. amostra ---------- */
const LIMITE = 14000;
const texto = msgs.filter((m) => !m.midia && m.texto.length > 1);
const linhaDe = (m) => '[' + iso(m.data) + '] ' + m.autor + ': ' + m.texto.replace(/\s+/g, ' ') + '\n';
const escolhidas = new Set();
let orcamento = LIMITE;
const tentar = (lista) => { for (const m of lista) { if (escolhidas.has(m)) continue; const custo = linhaDe(m).length; if (custo > orcamento) continue; escolhidas.add(m); orcamento -= custo; } };
tentar([...texto.slice(-90)].reverse());
tentar(texto.slice(0, 25));
const meio = texto.slice(25, -90);
const passo = Math.max(1, Math.ceil(meio.length / 120));
tentar(meio.filter((_, i) => i % passo === 0));
const amostra = texto.filter((m) => escolhidas.has(m)).map(linhaDe).join('');

/* ---------- 4. instruções ---------- */
const instrucoes = `Você escreve relatórios do Desvenda AI: uma leitura de conversas de casal, feita para a pessoa que enviou o histórico.

COMO ESCREVER
- Português brasileiro, segunda pessoa ("você"), tom de amigo próximo que não julga.
- Frases curtas. Nada de jargão ("métricas", "análise de sentimento", "algoritmo", "dados").
- Nunca diga o que a outra pessoa sente ou pensa. Descreva o que ela FAZ na conversa.
- Toda afirmação forte precisa de apoio: um número medido ou um trecho curto exato da conversa entre aspas (ex: "tudo bem por aí?", "deixa pra lá").
- Sempre que identificar um padrão ou atrito, cite a frase exata que a pessoa disse entre aspas ("..."). Isso dá prova concreta à leitura.
- Não invente números. Use só os que estão em NÚMEROS MEDIDOS.

COMO USAR O CONTEXTO FORNECIDO PELO USUÁRIO (QUIZ)
- O usuário respondeu a um questionário antes de enviar a conversa indicando sua percepção (relação, tempo de envolvimento, o que sente atualmente e o que quer descobrir).
- Use essas respostas como CONTEXTO para orientar o foco da análise e entender a perspectiva de quem está lendo.
- Compare objetivamente a percepção relatada pelo usuário com o histórico real da conversa e os números medidos.

O QUE ENTREGAR (array "sections" com exatamente 6 objetos):
1. RITMO — quem sustenta a conversa.
2. MUDANÇA — o que é diferente hoje do que era no começo (afeto, tom, volume).
3. UM ATRITO CONCRETO — desentendimento claro da conversa com data, horário e frase entre aspas.
4. O MECANISMO — o que cada um faz quando se incomoda (quem emudece, quem desconversa com piada, quem pede desculpas, quem cede).
5. UM HÁBITO QUE PASSA BATIDO — tema que morre sem conclusão, horário ou desculpa recorrente.
6. O QUE JÁ FUNCIONA — a única seção positiva.

Depois, exatamente 3 ações práticas e específicas para esta semana.`;

const contexto = respostas.length ? respostas.map((r) => '- ' + r.pergunta + ' ' + r.resposta).join('\n') : '- Não respondeu.';
const outros = porAutor.map((a) => a.autor).filter((n) => n !== remetente);

const quemEQuem = remetente
  ? 'QUEM É QUEM\n"' + remetente + '" é quem enviou a conversa e está lendo este relatório. Escreva "você" apenas para essa pessoa.\n\n'
  : '';

const pedido = `${quemEQuem}O QUE A PESSOA CONTOU ANTES DE ENVIAR\n${contexto}\n\nNÚMEROS MEDIDOS (contados no arquivo)\n${JSON.stringify(numeros)}\n\nAMOSTRA DA CONVERSA\n${amostra}\n\nAgora escreva o relatório em JSON.`;

return [{ json: { analiseId, callbackUrl, comAvancada, instrucoes, pedido } }];

// Confere a forma do relatório antes de devolver ao site.
const resposta = $input.first().json;
const preparo = $('Prepara o pedido').first().json;

const conteudo = resposta.choices && resposta.choices[0] && resposta.choices[0].message && resposta.choices[0].message.content;
if (!conteudo) throw new Error('Groq não devolveu conteúdo.');

let r;
try { r = JSON.parse(conteudo); } catch (e) { throw new Error('O relatório voltou fora do formato esperado.'); }

if (!Array.isArray(r.sections) || r.sections.length === 0) throw new Error('O relatório voltou sem seções.');

const ICONES = ['conversa', 'coracao', 'lupa', 'celular', 'presente', 'foguete', 'escudo', 'alerta'];
const rodizio = ['conversa', 'coracao', 'lupa', 'celular', 'presente', 'foguete'];

const sections = r.sections
  .filter((s) => s && s.title && s.body)
  .map((s, i) => ({ title: String(s.title), body: String(s.body), icon: ICONES.includes(s.icon) ? s.icon : rodizio[i % rodizio.length] }));

const acoes = Array.isArray(r.acoes)
  ? r.acoes.filter((a) => a && a.texto).map((a) => ({ titulo: String(a.titulo || ''), texto: String(a.texto) }))
  : [];

const corpo = {
  analiseId: preparo.analiseId,
  headline: String(r.headline || 'Sua análise está pronta.'),
  summary: String(r.summary || ''),
  patternCount: Number(r.patternCount) > 0 ? Math.round(Number(r.patternCount)) : sections.length,
  sections,
  acoes
};

if (preparo.comAvancada && r.advanced && r.advanced.body) {
  const nivel = String(r.advanced.level || 'baixo').toLowerCase();
  corpo.advanced = {
    title: String(r.advanced.title || 'Análise avançada de traição'),
    body: String(r.advanced.body),
    level: nivel === 'alto' || nivel === 'medio' ? nivel : 'baixo'
  };
}

return [{ json: { callbackUrl: preparo.callbackUrl, corpo } }];

const wh = $('Recebe a conversa').first().json;
const corpo = wh.body || wh || {};
const analiseId = corpo.analiseId || corpo.analysisId;
const callbackUrl = corpo.callbackUrl;
if (!callbackUrl) throw new Error('Sem callbackUrl para avisar a falha.');

const entrada = $input.first().json || {};
const detalhe = entrada.error || entrada.message || 'A leitura não foi concluída.';

return [{ json: { callbackUrl, corpo: { analiseId, erro: String(detalhe).slice(0, 200) } } }];
